CREATE TABLE IF NOT EXISTS public.event_layouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.events(id) ON DELETE CASCADE, name text DEFAULT 'Layout 1', width numeric DEFAULT 1000, height numeric DEFAULT 1000, objects jsonb DEFAULT '[]'::jsonb, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now()); ALTER TABLE public.event_layouts ENABLE ROW LEVEL SECURITY; CREATE POLICY "Permitir todo a autenticados" ON public.event_layouts FOR ALL USING (auth.role() = 'authenticated');
